from audit_helpers import *
rows=[(53,201,r'\chi_{-i} =\chi_0(x^{q^i})',r'\chi_{-i}(x) =\chi_0(x^{q^i})','Keep the printed implicit function-variable notation; the surrounding sentence uniquely specifies the characters.'),(54,206,r'\h^\bullet(\dG_a,\sF(\psi))',r'\h_c^\bullet(\dG_a,\sF(\psi))','Both ordinary and compactly supported cohomology vanish here. The printed equality is true and needs no normalization.'),(55,211,r'\chi_\lambda:\gal(\bar F/F)^\mathrm{ab}\to E_\lambda',r'\chi_\lambda:\gal(\bar F/F)^\mathrm{ab}\to E_\lambda^\ast','The printed target field is a conventional way to state a character with values in that field; a unit-group superscript is not necessary to correct a false statement.'),(56,215,r'i\in I',r'i\in\beta','The condition that i corresponds to an embedding of e_beta already forces membership in beta. The printed I is correct and should remain.'),(57,222,r'\psi^{-1}\sigma; \sF(\psi) in 7.9(iii)',r'\psi\sigma; \sF(\psi\sigma) in 7.9(iii)','The inverse character in the base-change open is visibly printed and serves the duality argument; retain it. The lemma uses the locally clear abbreviated pullback notation F(psi).'),(58,224,r'\delta:i_!(\sG\otimes\eR^{n-1}\pi_!\sF(\psi))',r'\delta:i_!(\sG\otimes\eR^{n-1}\pi_!\sF(\psi\sigma))','The source of delta visibly abbreviates the pullback sheaf as F(psi); this shorthand has a unique local meaning.'),(59,225,r'\eR^q\pi_!\sF(\psi); \dim\,{}^\prime E_2^{pq}=1+n',r'\eR^q\pi_!\sF(\psi\sigma); \dim\,{}^\prime E_2^{1,n-1}=1+n','Restore printed sheaf abbreviation and the general p,q indices. The immediately preceding sentence singles out the only nonzero bidegree, so no mathematical correction is required.'),(60,226,r'\tau^\ast\eR^{n-1}\pi_!\sF(\psi)',r'\tau^\ast\eR^{n-1}\pi_!\sF(\psi\sigma)','In item7.15(a) the scan uses the sheaf abbreviation F(psi); retain it rather than silently expanding the argument.')]
for n,p,pr,tex,reason in rows:
 own(n,p,'English propagation of retained printed notation; comparison with corrected tree',pr,tex,pr,'transcription',reason)
# English-only surface slips, independent of source readings.
for n,p,old,new,reason in [(61,200,'a E_lambda-sheaf','an E_lambda-sheaf','Correct English indefinite article before the vowel sound E; no French content change.'),(62,210,'is a algebraic number','is an algebraic number','Correct English indefinite article.'),(63,211,'a ell-adic cohomology argument','an ell-adic cohomology argument','Correct English indefinite article before ell.'),(64,218,'a odd character','an odd character','Correct English indefinite article.'),(65,226,'are easy to calculated easily','are easy to calculate','The English translation duplicates the adverb and retains a past participle after to; restore the direct meaning of the printed se calculent aisément.')]:
 own(n,p,'English translation surface slip',new,old,new,'translation',reason)
# Avoid adding a second opening parenthesis in an already translated parenthetical phrase.
p=BASE/'edits.jsonl';rs=[json.loads(x) for x in p.read_text().splitlines()]
